<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\PaymentGateway; use Illuminate\Http\Request; use Illuminate\Support\Str;
class PaymentGatewayController extends Controller { public function index(){return view('admin.payment_gateways.index',['items'=>PaymentGateway::orderBy('sort_order')->get()]);} public function store(Request $r){$d=$this->validated($r);PaymentGateway::create([...$d,'slug'=>$d['slug']?:Str::slug($d['name']),'credentials'=>$this->credentials($r),'settings'=>$this->settings($r),'is_enabled'=>$r->boolean('is_enabled'),'is_test_mode'=>$r->boolean('is_test_mode')]);return back()->with('success','Payment gateway added.');} public function update(Request $r,PaymentGateway $paymentGateway){$d=$this->validated($r);$data=[...$d,'slug'=>$d['slug']?:Str::slug($d['name']),'settings'=>$this->settings($r),'is_enabled'=>$r->boolean('is_enabled'),'is_test_mode'=>$r->boolean('is_test_mode')];if($r->filled('api_key')||$r->filled('api_secret'))$data['credentials']=$this->credentials($r);$paymentGateway->update($data);return back()->with('success','Payment gateway updated.');} public function destroy(PaymentGateway $paymentGateway){$paymentGateway->delete();return back()->with('success','Payment gateway deleted.');}
 private function validated(Request $r):array{return $r->validate(['name'=>'required|string|max:120','slug'=>'nullable|string|max:120','provider'=>'required|string|max:80','currency'=>'required|string|size:3','sort_order'=>'nullable|integer|min:0','callback_url'=>'nullable|url|max:2048','webhook_url'=>'nullable|url|max:2048','initialize_url'=>'nullable|url|max:2048','timeout'=>'nullable|integer|min:5|max:120','webhook_secret'=>'nullable|string|max:255','api_key'=>'nullable|string|max:2000','api_secret'=>'nullable|string|max:2000']);}
 private function credentials(Request $r):array{return array_filter(['api_key'=>$r->api_key,'api_secret'=>$r->api_secret],fn($v)=>filled($v));}
 private function settings(Request $r):array{return array_filter(['callback_url'=>$r->callback_url,'webhook_url'=>$r->webhook_url,'initialize_url'=>$r->initialize_url,'timeout'=>$r->timeout,'webhook_secret'=>$r->webhook_secret],fn($v)=>filled($v));}
}
